@If(CurrDueDate = "";@Return(@Do(@Command([EditGotoField];"CurrDueDate");@Prompt([Ok];"Warning!";"Please select the due date before proceeding!")));"");

@If(CurrDueDate <=@Today;@Return(@Do(@Command([EditGotoField];"CurrDueDate");@Prompt([Ok];"Warning!";"Invalid date selection!! The response date should be 7 working days from the QACAR Request issue date!")));"");

