(@Today >= When1 | @Today >= When2 | @Today >= When3 |@Today >=  When4 | @Today >= When5 |@Today >=  When6 |@Today >=  When7 | @Today >= When8 | @Today >= When9 |@Today >=  When10 |@Today >=  When11 |@Today >=  When12 | @Today >= When13 |@Today >=  When14) | (Status = "Awaiting Completion" & @Today >= ComDate) & ReminderDate <= @Today};

